const input = $input.first().json;

let rawQuery = '';
let sheetId = input.sheetId || '';
let directTransactions = null;

// 1. Support direct transactions array passing: { transactions: [...] }
if (Array.isArray(input.directTransactions) && input.directTransactions.length > 0) {
  directTransactions = input.directTransactions;
} else if (Array.isArray(input.transactions) && input.transactions.length > 0) {
  directTransactions = input.transactions;
}

// 2. If input.query is an object: { query: '...', sheetId: '...' }
if (input.query && typeof input.query === 'object') {
  if (Array.isArray(input.query.directTransactions)) {
    directTransactions = input.query.directTransactions;
  } else if (Array.isArray(input.query.transactions)) {
    directTransactions = input.query.transactions;
  }
  rawQuery = input.query.query || input.query.text || '';
  if (!sheetId && input.query.sheetId) {
    sheetId = input.query.sheetId;
  }
} else if (typeof input.query === 'string') {
  rawQuery = input.query;
} else if (typeof input.text === 'string') {
  rawQuery = input.text;
} else if (Array.isArray(input.queries)) {
  rawQuery = input.queries.join('\n');
}

// 3. If rawQuery is not a string, stringify safely
if (typeof rawQuery !== 'string') {
  try {
    rawQuery = JSON.stringify(rawQuery);
  } catch(e) {
    rawQuery = '';
  }
}

// 4. Extract sheetId if embedded in text
const match = rawQuery.match(/sheetId:\s*([^\s\n\r]+)/i);
if (match && !sheetId) {
  sheetId = match[1].trim();
}

// 5. Clean rawQuery to pure message text
rawQuery = rawQuery
  .replace(/^query:\s*/i, '')
  .replace(/sheetId:\s*([^\s\n\r]+)/ig, '')
  .trim();

// 6. Final fallback for sheetId from any nested property
if (!sheetId) {
  for (const k of Object.keys(input)) {
    if (typeof input[k] === 'object' && input[k] && input[k].sheetId) {
      sheetId = input[k].sheetId;
      break;
    }
  }
}

// --- HYBRID CLASSIFICATION: REGEX STRUCTURAL ANCHOR LAYER ---
const amountRegex = /(?:rs\.?|inr|rupees|₹|\$)?\s*(\d+(?:,\d+)*(?:\.\d{1,2})?)\s*(?:rs\.?|inr|rupees|₹)?/gi;
const amounts = [];
let am;
while ((am = amountRegex.exec(rawQuery)) !== null) {
  const rawNum = am[1].replace(/,/g, '');
  const val = parseFloat(rawNum);
  const isYear = val >= 2020 && val <= 2030 && !/(?:rs|inr|rupees|₹|\$)/i.test(am[0]);
  if (val > 0 && !isYear) {
    const prefix = rawQuery.substring(Math.max(0, am.index - 10), am.index).toLowerCase();
    if (!/\b(?:order|txn|ref|id|otp|code|#)\s*:?$/i.test(prefix)) {
      amounts.push(val);
    }
  }
}

let direction = 'unknown';
if (/\b(?:received|got|credited|deposit|salary|refund|cashback|earned|won|income)\b/i.test(rawQuery)) {
  direction = 'credit';
} else if (/\b(?:spent|paid|bought|debited|debit|charged|purchased|cost|sent|transferred|loss)\b/i.test(rawQuery)) {
  direction = 'debit';
}

let medium = 'other';
if (/\b(?:upi|gpay|phonepe|paytm|bhim|vpa)\b/i.test(rawQuery)) {
  medium = 'upi';
} else if (/\b(?:card|pos|atm)\b/i.test(rawQuery)) {
  medium = 'card';
} else if (/\b(?:bank|neft|rtgs|imps|account|ac|a\/c)\b/i.test(rawQuery)) {
  medium = 'bank';
} else if (/\b(?:cash)\b/i.test(rawQuery)) {
  medium = 'cash';
}

const catHints = [];
if (/\b(?:swiggy|zomato|zepto|blinkit|eat|food|cafe|restaurant|tea|chai|coffee|mcdonald|kfc|starbucks|domino|pizza|dine|biryani|lunch|dinner|breakfast|snacks)\b/i.test(rawQuery)) {
  catHints.push('Food & Dining');
}
if (/\b(?:uber|ola|rapido|metro|irctc|railway|train|flight|bus|auto|cab|petrol|fuel|shell|hp|indianoil)\b/i.test(rawQuery)) {
  catHints.push('Travel');
}
if (/\b(?:amazon|flipkart|myntra|meesho|zara|h&m|nykaa|ajio|croma|shopping|store|mart|mall|sunscreen|toner|serum)\b/i.test(rawQuery)) {
  catHints.push('Shopping');
}
if (/\b(?:electricity|water|gas|wifi|broadband|airtel|jio|vi|bill|recharge|dth|rent)\b/i.test(rawQuery)) {
  catHints.push('Bills & Utilities');
}
if (/\b(?:salary|payroll|stipend)\b/i.test(rawQuery)) {
  catHints.push('Salary Income');
}

const anchorList = [];
if (amounts.length > 0) anchorList.push(`Detected Amounts: [${[...new Set(amounts)].join(', ')}]`);
if (direction !== 'unknown') anchorList.push(`Direction Signal: ${direction}`);
if (medium !== 'other') anchorList.push(`Medium: ${medium}`);
if (catHints.length > 0) anchorList.push(`Likely Categories: [${[...new Set(catHints)].join(', ')}]`);

const regexAnchors = anchorList.join(' | ') || 'None';


// --- FAST-PATH DETECTION FOR UNAMBIGUOUS TRANSACTIONS ---
let matchedVendor = '';
const vendorRules = [
  { regex: /\b(swiggy|zomato|zepto|blinkit|mcdonald'?s?|kfc|starbucks|domino'?s?|subway|pizza hut|burger king|chai point|chaayos)\b/i, category: 'Food & Dining' },
  { regex: /\b(uber|ola|rapido|irctc|redbus|makemytrip|indigo|air india|petrol|fuel|shell|hp pump)\b/i, category: 'Travel' },
  { regex: /\b(amazon|flipkart|myntra|meesho|nykaa|ajio|zara|h&m|croma|reliance digital|dmart)\b/i, category: 'Shopping' },
  { regex: /\b(airtel|jio|vi|vodafone|bescom|tneb|adani electricity|tata power|rent|wifi)\b/i, category: 'Bills & Utilities' },
  { regex: /\b(cult\.?fit|apollo pharmacy|pharmeasy|netmeds|1mg)\b/i, category: 'Health & Fitness' }
];

for (const rule of vendorRules) {
  const m = rawQuery.match(rule.regex);
  if (m) {
    matchedVendor = m[1];
    if (!catHints.includes(rule.category)) catHints.push(rule.category);
    break;
  }
}

let skipLLM = false;
if (directTransactions && Array.isArray(directTransactions) && directTransactions.length > 0) {
  skipLLM = true;
} else if (amounts.length === 1 && direction !== 'unknown' && matchedVendor) {
  // Clean single transaction with high confidence
  directTransactions = [{
    amount: amounts[0],
    type: direction === 'credit' ? 'credit' : 'debit',
    targetParty: matchedVendor.charAt(0).toUpperCase() + matchedVendor.slice(1),
    category: catHints[0] || 'Shopping',
    medium: medium,
    description: rawQuery,
    confidence: 'HIGH'
  }];
  skipLLM = true;
}

return {
  json: {
    ...input,
    query: rawQuery,
    sheetId: sheetId,
    directTransactions: directTransactions,
    skipLLM: skipLLM,
    regexAnchors: regexAnchors,
    detectedAmounts: [...new Set(amounts)],
    detectedDirection: direction
  }
};

const norm = $('Input Normalizer1').item.json;
const rawInput = $input.item.json;
const content = rawInput?.choices?.[0]?.message?.content || '';
const reasoning = rawInput?.choices?.[0]?.message?.reasoning_content || '';
const rawText = content.trim() || reasoning.trim();

let devData = null;

// If direct transactions were provided in the input, use them directly
if (norm.directTransactions && Array.isArray(norm.directTransactions) && norm.directTransactions.length > 0) {
  devData = { isNull: false, transactions: norm.directTransactions };
}

if (!devData && rawText) {
  try {
    const cleaned = rawText
      .replace(/<think>[\s\S]*?<\/think>/gi, '')
      .replace(/```json/gi, '')
      .replace(/```/gi, '')
      .trim();

    const match = cleaned.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
    if (match) {
      const parsed = JSON.parse(match[0]);
      if (Array.isArray(parsed)) {
        devData = { isNull: false, transactions: parsed };
      } else {
        devData = parsed;
      }
    }
  } catch(e) {
    devData = null;
  }
}

// Resilient Fallback Line-by-Line Regex Parser: only run if unparseable, NEVER if explicitly null
const isExplicitNull = devData && devData.isNull === true;
if (!devData || (!isExplicitNull && !devData.transactions && devData.amount === undefined)) {
  const query = norm.query || '';
  const lines = query.split(/[\n,;]+|\band\b/i).map(s => s.trim()).filter(Boolean);
  const fallbackList = [];

  for (const line of lines) {
    const amtMatch = line.match(/(?:rs\.?|inr|rupees|₹|\$)?\s*(\d+(?:\.\d{1,2})?)/i) || line.match(/(\d+(?:\.\d{1,2})?)\s*(?:rs\.?|inr|rupees|₹)?/i);
    if (amtMatch) {
      const amt = parseFloat(amtMatch[1]);
      if (amt > 0) {
        let item = line
          .replace(/(?:rs\.?|inr|rupees|₹|\$)\s*\d+(?:\.\d{1,2})?/gi, ' ')
          .replace(/\d+(?:\.\d{1,2})?\s*(?:rs\.?|inr|rupees|₹)?/gi, ' ')
          .replace(/\b(?:bought|spent|paid|for|of|on|a|an|the|to)\b/gi, ' ')
          .trim()
          .replace(/\s+/g, ' ');
        fallbackList.push({
          amount: amt,
          type: 'debit',
          targetParty: item || 'Unknown',
          category: 'Shopping'
        });
      }
    }
  }

  if (fallbackList.length > 1) {
    devData = { isNull: false, transactions: fallbackList };
  } else if (fallbackList.length === 1) {
    devData = {
      isNull: false,
      amount: fallbackList[0].amount,
      type: 'debit',
      targetParty: fallbackList[0].targetParty,
      category: 'Shopping'
    };
  }
}

if (!devData) {
  devData = { isNull: true, amount: 0, targetParty: 'Unknown' };
}

// 1. Support multi-item transactions array (Bulk list)
if (devData.transactions && Array.isArray(devData.transactions) && devData.transactions.length > 0) {
  return devData.transactions.map((tx, idx) => {
    const amt = parseFloat(tx.amount) || 0;
    const vendor = (tx.targetParty || tx.vendor || tx.item || 'Unknown').trim();
    return {
      json: {
        ...norm,
        batchIndex: idx,
        totalInBatch: devData.transactions.length,
        isNull: false,
        hasMissingData: amt === 0,
        missingFields: amt === 0 ? 'Amount' : '',
        amount: amt,
        category: tx.category || 'Shopping',
        vendor: vendor || 'Unknown',
        type: ((tx.type || 'debit').toLowerCase() === 'credit' || (tx.type || '').toLowerCase() === 'income') ? 'Income' : 'Expense',
        medium: tx.medium || 'other',
        description: tx.description || '',
        date: tx.date_of_transaction || tx.date || new Date().toISOString().split('T')[0]
      }
    };
  });
}

// 2. Single transaction flow
const amount = parseFloat(devData.amount) || 0;
const confidence = (devData.confidence || 'HIGH').toUpperCase();
let missingFields = Array.isArray(devData.missing) ? [...devData.missing] : [];

if (confidence === 'LOW') {
  devData.isNull = true;
} else if (confidence === 'MEDIUM' && missingFields.length === 0) {
  missingFields.push('Confirmation needed');
}

if (amount === 0 && !devData.isNull) missingFields.push('Amount');
if (!devData.targetParty && !devData.isNull) missingFields.push('Merchant');

const isTransactionNull = devData.isNull === true || (amount === 0 && !devData.targetParty);

return [{
  json: {
    ...norm,
    isNull: isTransactionNull,
    hasMissingData: missingFields.length > 0 && !isTransactionNull,
    missingFields: missingFields.join(', '),
    amount,
    category: devData.category || 'Other',
    vendor: devData.targetParty || 'Unknown',
    type: (devData.type || 'debit').toLowerCase() === 'credit' ? 'Income' : 'Expense',
    medium: devData.medium || 'other',
    description: devData.description || '',
    date: devData.date_of_transaction || new Date().toISOString().split('T')[0]
  }
}];

return { 
  json: { 
    status: 'MISSING_DATA',
    response: `Missing data: ${$('Clean & Format').item.json.missingFields}. Ask the user to provide it.`,
    missingFields: $('Clean & Format').item.json.missingFields
  } 
};

return { 
  json: { 
    status: 'NOT_TRANSACTION',
    response: 'Message was not a valid financial transaction.'
  } 
};

const items = $input.all();
const first = items[0]?.json || {};
const sheetId = first.sheetId || $('Input Normalizer1').first().json.sheetId;

return [{
  json: {
    sheetId: sheetId,
    batchCount: items.length
  }
}];

const pastRows = $input.all().map(i => i.json);

// Safely retrieve all candidate transactions that passed validation
let candidateItems = [];
const candidateNodes = ['Is Data Missing?1', 'Clean & Format', 'Clean & Format1'];
for (const name of candidateNodes) {
  try {
    const nodeItems = $(name).all().map(i => i.json);
    const validOnes = nodeItems.filter(tx => tx && !tx.isNull && !tx.hasMissingData && parseFloat(tx.amount) > 0);
    if (validOnes.length > 0) {
      candidateItems = validOnes;
      break;
    }
  } catch(e) {}
}

const validToInsert = [];
const duplicateList = [];

for (const currentTx of candidateItems) {
  const txDate = new Date(currentTx.date || new Date().toISOString().split('T')[0]);
  const currentAmt = parseFloat(currentTx.amount);
  const currentVendorClean = String(currentTx.vendor || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  const currentRef = String(currentTx.refId || currentTx.eventId || currentTx.orderId || currentTx.upiRef || '');
  const currentDesc = String(currentTx.description || '').toLowerCase().trim();

  let isDup = false;
  let dupReason = '';
  let reviewSignal = null;

  // 1. Check against existing rows from the Google Sheet
  if (pastRows.length > 0 && pastRows[0] && pastRows[0].amount !== undefined) {
    for (const pt of pastRows) {
      if (!pt || pt.amount === undefined || String(pt.type || '').toLowerCase() === 'deleted') continue;
      const ptAmt = parseFloat(pt.amount);
      if (isNaN(ptAmt) || ptAmt !== currentAmt) continue;

      const ptVendorClean = String(pt.vendor || '').toLowerCase().replace(/[^a-z0-9]/g, '');
      const ptDesc = String(pt.description || '').toLowerCase().trim();
      const ptRef = String(pt.refId || pt.eventId || pt.orderId || pt.upiRef || '');

      // A. Authoritative idempotency check: Match on stable event/ref ID
      if (currentRef && (ptRef === currentRef || ptDesc.includes(currentRef.toLowerCase()))) {
        isDup = true;
        dupReason = `Idempotent duplicate: Ref ID ${currentRef} already logged.`;
        break;
      }

      // Safe date comparison guarding against NaN
      let diffDays = 999;
      if (pt.date) {
        const ptDate = new Date(pt.date);
        if (!isNaN(ptDate.getTime()) && !isNaN(txDate.getTime())) {
          diffDays = Math.abs((txDate - ptDate) / (1000 * 60 * 60 * 24));
        }
      }

      // Exact vendor match on the same calendar day
      if (diffDays <= 0.5) {
        const isExactVendor = currentVendorClean === ptVendorClean && currentVendorClean.length > 0;
        const isFuzzyVendor = (ptVendorClean.includes(currentVendorClean) && currentVendorClean.length >= 3) ||
                              (currentVendorClean.includes(ptVendorClean) && ptVendorClean.length >= 3);

        if (isExactVendor) {
          // If description is identical or both lack distinguishing details, mark duplicate
          if (currentDesc === ptDesc || (!currentDesc && !ptDesc)) {
            isDup = true;
            dupReason = `Matches past transaction today: Rs.${pt.amount} at ${pt.vendor}`;
            break;
          }
        } else if (isFuzzyVendor) {
          // Fuzzy matching is treated as a review signal, NOT a basis for discarding
          reviewSignal = `Similar vendor (${pt.vendor}) recorded today`;
        }
      }
    }
  }

  // 2. Intra-batch deduplication (prevent duplicate identical items in same list)
  if (!isDup) {
    for (const accepted of validToInsert) {
      const acceptedAmt = parseFloat(accepted.amount);
      const acceptedVendorClean = String(accepted.vendor || '').toLowerCase().replace(/[^a-z0-9]/g, '');
      const acceptedDesc = String(accepted.description || '').toLowerCase().trim();

      if (acceptedAmt === currentAmt && acceptedVendorClean === currentVendorClean && acceptedDesc === currentDesc) {
        isDup = true;
        dupReason = `Duplicate item in current batch: Rs.${currentTx.amount} at ${currentTx.vendor}`;
        break;
      }
    }
  }

  if (isDup) {
    duplicateList.push({
      ...currentTx,
      isDuplicate: true,
      duplicateReason: dupReason
    });
  } else {
    validToInsert.push({
      ...currentTx,
      isDuplicate: false,
      duplicateReason: '',
      reviewSignal: reviewSignal
    });
  }
}

// If ALL candidate items were duplicates
if (validToInsert.length === 0) {
  const reasons = duplicateList.map(d => `${d.vendor} (Rs.${d.amount}): ${d.duplicateReason}`).join('; ');
  return [{
    json: {
      isDuplicate: true,
      status: 'SKIPPED_DUPLICATE',
      duplicateReason: reasons || 'All transactions matched existing entries.',
      skippedDuplicatesCount: duplicateList.length
    }
  }];
}

// Return clean items for bulk append with standard Transactions columns
const skippedSummary = duplicateList.map(d => `${d.vendor} (Rs.${d.amount})`).join(', ');
return validToInsert.map(tx => ({
  json: {
    sheetId: tx.sheetId,
    date: tx.date,
    amount: tx.amount,
    vendor: tx.vendor,
    category: tx.category,
    type: tx.type,
    medium: tx.medium || 'other',
    description: tx.description || '',
    isDuplicate: false,
    skippedDuplicatesCount: duplicateList.length,
    skippedDuplicatesSummary: skippedSummary
  }
}));

const dup = $input.first().json;
return { 
  json: { 
    status: 'SKIPPED_DUPLICATE',
    response: `Skipped because it looks like duplicate transaction(s): ${dup.duplicateReason}`,
    duplicateReason: dup.duplicateReason,
    skippedCount: dup.skippedDuplicatesCount || 1
  } 
};

const items = $input.all().map(i => i.json);
let itemStrings = items.map(tx => `Rs.${tx.amount} at ${tx.vendor} (${tx.category})`).join(', ');

const firstItem = items[0] || {};
const skippedCount = firstItem.skippedDuplicatesCount || 0;
let skippedNote = '';
if (skippedCount > 0) {
  skippedNote = ` (Skipped ${skippedCount} duplicate: ${firstItem.skippedDuplicatesSummary})`;
}

return {
  json: {
    status: 'SUCCESS',
    response: `Successfully logged ${items.length} transaction(s): ${itemStrings}.${skippedNote}. Inform the user cheerfully in one short sentence.`,
    items: items,
    totalLogged: items.length,
    skippedCount: skippedCount
  }
};
